g=[[0]*12 for _ in range(11)]
rows=[[6],[5,6,7],[7],[6,7,8],[6,7]]
for i,cols in enumerate(rows):
    for c in cols: g[1+i][c]=4
# horizontal mirror to the left: c -> 9 - c
mir=[[9-c for c in cols] for cols in rows]
for i,cols in enumerate(mir):
    for c in cols: g[1+i][c]=4
for r in g: print(r)
